// =============== REPASOS ===============
// La curva del olvido (Ebbinghaus): sin repasar se olvida rápido; cada repaso a tiempo sube el recuerdo y lo vuelve más lento de olvidar.

// La tarjeta del tema «vuela» por la semana y cae en el día en que vuelve el tema: lejos si aciertas, cerca si fallas.
const ESTILO_VUELA = `<style>@keyframes vuela{0%{transform:translate(0,0) scale(.7);opacity:0}15%{opacity:1}70%{transform:translate(var(--to),-14px) scale(1)}100%{transform:translate(var(--to),0) scale(1);opacity:1}}.vuela{animation:vuela 1.8s cubic-bezier(.23,1,.32,1) .6s both}@keyframes cae{0%,80%{background:#FFFFFF}100%{background:var(--c)}}.cae{animation:cae 2.4s ease both}@media (prefers-reduced-motion:reduce){.vuela{animation:none;transform:translate(var(--to),0)}.cae{animation:none;background:var(--c)}}</style>`;
const vueloEco = (dia, col, fondo, etiqueta) => { const celda=38, gap=6, to=(dia)*(celda+gap); const dias=['Hoy','Mañana','2 d','3 d','4 d','5 d','6 d'];
  return `<div style="position:relative;display:flex;gap:${gap}px;margin-top:8px">${dias.map((d,i)=>`<span style="display:flex;flex-direction:column;align-items:center;gap:4px;width:${celda}px"><span class="${i===dia?'cae':''}" style="--c:${fondo};width:${celda}px;height:30px;border-radius:9px;border:2px solid ${i===dia?col:C.borde};background:#FFFFFF;animation-delay:${i===dia?'.4s':'0s'}"></span><span style="font-size:11px;font-weight:${i===dia?700:500};color:${i===dia?C.tinta:C.suave}">${d}</span></span>`).join('')}
<span class="vuela" aria-hidden="true" style="--to:${to}px;position:absolute;left:6px;top:4px;width:26px;height:20px;border-radius:6px;border:3px solid ${col};background:#FFFFFF"></span></div><p style="margin:6px 0 0;font-size:13px;font-weight:700;color:${C.tinta}">${etiqueta}</p>`; };
const curvaOlvido = () => { const W=520, H=230, X=d=>24+d*(W-84)/21, Y=p=>H-34-(H-70)*p/100;
  const sin = Array.from({length:85},(_,i)=>i/4).map(d=>`${X(d).toFixed(1)},${Y(Math.max(8,100*Math.exp(-d/1.6))).toFixed(1)}`).join(' ');
  const seg=[[0,1,1.5],[1,3,4],[3,7,9],[7,21,30]]; let con=[]; for(const[a,b,s]of seg){ for(let d=a; d<=b+1e-9; d+=0.25) con.push(`${X(d).toFixed(1)},${Y(100*Math.exp(-(d-a)/s)).toFixed(1)}`); }
  const reps=[[1,'1 día'],[3,'3 días'],[7,'1 semana'],[21,'3 semanas']];
  return `<svg width="100%" viewBox="0 0 ${W} ${H}" role="img" aria-label="Sin repasar, el recuerdo cae a menos del 20 % en tres días. Con repasos al día 1, 3, 7 y 21, el recuerdo vuelve al 100 % cada vez y cae cada vez más despacio.">
<defs><linearGradient id="olv" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#00C2A8" stop-opacity=".22"/><stop offset="1" stop-color="#00C2A8" stop-opacity="0"/></linearGradient></defs>
<line x1="${X(0)}" x2="${X(21)}" y1="${Y(0)}" y2="${Y(0)}" stroke="${C.borde}"/>
<polyline class="dibuja" points="${sin}" fill="none" stroke="#B4BDCB" stroke-width="3" stroke-dasharray="6 6" pathLength="100" style="stroke-dasharray:100"/>
<text x="${X(2.2)}" y="${Y(4)}" font-size="13" font-weight="600" fill="${C.suave}">Sin repasar</text>
<polygon class="aparece" points="${X(0)},${Y(0)} ${con.join(' ')} ${X(21)},${Y(0)}" fill="url(#olv)"/>
<polyline class="dibuja" points="${con.join(' ')}" fill="none" stroke="#00C2A8" stroke-width="4" stroke-linejoin="round" stroke-linecap="round" pathLength="100"/>
${reps.map(([d,t],i)=>`<g class="entra" style="animation-delay:${(.6+i*.25).toFixed(2)}s"><line x1="${X(d)}" x2="${X(d)}" y1="${Y(100)}" y2="${Y(0)}" stroke="#00C2A8" stroke-width="1.5" stroke-dasharray="3 4" opacity=".6"/><rect x="${X(d)-13}" y="${Y(100)-24}" width="26" height="18" rx="5" fill="#FFFFFF" stroke="#00C2A8" stroke-width="2.5"/><circle cx="${X(d)-5}" cy="${Y(100)-15}" r="2.2" fill="${C.tinta}"/><circle cx="${X(d)+5}" cy="${Y(100)-15}" r="2.2" fill="${C.tinta}"/><text x="${X(d)}" y="${H-10}" text-anchor="middle" font-size="13" font-weight="700" fill="${C.tinta}">${t}</text></g>`).join('')}

<text x="${X(14)}" y="${Y(86)}" text-anchor="middle" font-size="13" font-weight="700" fill="${C.mentaT}">Con repasos</text>
</svg>`; };

