const qr = (t=220) => { const n=25, s=t/n; let r=''; let x=7; const fijo=(i,j)=>(i<7&&j<7)||(i<7&&j>=n-7)||(i>=n-7&&j<7); for(let i=0;i<n;i++)for(let j=0;j<n;j++){ if(fijo(i,j))continue; x=(x*1103515245+12345)&0x7fffffff; if(x%100<48) r+=`<rect x="${(j*s).toFixed(1)}" y="${(i*s).toFixed(1)}" width="${s.toFixed(1)}" height="${s.toFixed(1)}"/>`; }
  const ojo=(a,b)=>`<rect x="${b*s}" y="${a*s}" width="${7*s}" height="${7*s}" fill="none" stroke="${C.tinta}" stroke-width="${s}" transform="translate(${s/2} ${s/2}) scale(${(6/7).toFixed(3)})" transform-origin="${b*s} ${a*s}"/><rect x="${(b+2)*s}" y="${(a+2)*s}" width="${3*s}" height="${3*s}"/>`;
  return `<svg width="${t}" height="${t}" viewBox="0 0 ${t} ${t}" role="img" aria-label="Tu código QR de asistencia" fill="${C.tinta}">${r}${ojo(0,0)}${ojo(0,n-7)}${ojo(n-7,0)}</svg>`; };
