const anilloVivo = (p, t=130) => { const r=t/2-12, L=2*Math.PI*r, [c1,c2] = p>=85?[C.tq,'#5CCBFF']:[C.tq,C.sol];
  return `<svg width="${t}" height="${t}" viewBox="0 0 ${t} ${t}" role="img" aria-label="${p} % del curso"><defs><linearGradient id="av${p}" gradientUnits="userSpaceOnUse" x1="${t/2+r}" y1="${t/2}" x2="${(t/2+r*Math.cos(2*Math.PI*Math.min(p,50)/100)).toFixed(1)}" y2="${(t/2+r*Math.sin(2*Math.PI*Math.min(p,50)/100)).toFixed(1)}"><stop offset="0" stop-color="${c1}"/><stop offset="1" stop-color="${c2}"/></linearGradient></defs><circle cx="${t/2}" cy="${t/2}" r="${r}" fill="none" stroke="rgba(255,255,255,.8)" stroke-width="14"/><circle class="anillo" style="--total:${L.toFixed(1)}" cx="${t/2}" cy="${t/2}" r="${r}" fill="none" stroke="url(#av${p})" stroke-width="14" stroke-linecap="round" stroke-dasharray="${L.toFixed(1)}" stroke-dashoffset="${(L*(1-p/100)).toFixed(1)}" transform="rotate(-90 ${t/2} ${t/2})"/><text x="50%" y="50%" text-anchor="middle" dominant-baseline="central" font-family="Poppins,sans-serif" font-weight="700" font-size="${Math.round(t/4.3)}" fill="${C.tinta}">${p} %</text></svg>`; };
