// --- Bloques: el mismo ejercicio armado con piezas en español; el juez lo califica igual ---
const CATB = { datos:['#D5F6F0','#00A38D','Datos'], mostrar:['#E3F4FF','#1F6FA3','Mostrar'], ops:['#FFF1C2','#C98A00','Operaciones'], decidir:['#F3EAFB','#7A3FB0','Decidir'], repetir:['#FFE9DC','#C2551B','Repetir'] };
const ranura = (t, tipo='') => `<span style="display:inline-flex;align-items:center;gap:4px;padding:3px 10px;border-radius:999px;background:#FFFFFF;border:1px solid ${tipo?CATB[tipo][1]:'#CBD5E1'};font-size:14px;font-weight:600">${t}</span>`;
const bloque = (cat, html, sel=false, sangria=0) => `<div class="entra" style="position:relative;align-self:flex-start;min-width:340px;margin-left:${sangria}px;display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:10px 14px 10px 18px;border-radius:12px;background:${CATB[cat][0]};border:2px solid ${sel?C.tinta:CATB[cat][1]};font-size:15px;font-weight:700;color:${C.tinta};box-shadow:0 2px 0 ${CATB[cat][1]}"><span aria-hidden="true" style="position:absolute;left:22px;top:-7px;width:22px;height:8px;border-radius:0 0 6px 6px;background:${CATB[cat][0]};border:2px solid ${CATB[cat][1]};border-top:0"></span><span aria-hidden="true" style="position:absolute;left:0;top:8px;bottom:8px;width:5px;border-radius:0 4px 4px 0;background:${CATB[cat][1]}"></span>${html}</div>`;
