const editorV5 = (marca, tooltip) => `<div style="flex:1;min-height:0;position:relative;padding:12px 0;font:16px/1.9 'JetBrains Mono',monospace;color:#E2E8F0;overflow:hidden">
${linea(1,`${palabra('const',K.kw)} base = ${palabra('leerNumero',K.fn,tooltip)}();`)}
${linea(2,`${palabra('const',K.kw)} altura = ${palabra('leerNumero',K.fn)}();`)}
${linea(3,'')}
${linea(4,`${palabra('console.log',K.fn)}(base ${palabra('*',K.kw)} altura);`)}
${linea(5,`${palabra('console.log',K.fn)}(${marca?`<span style="border-bottom:2px wavy ${C.sol}">`:''}${tok('2',K.num)} * base + altura${marca?'</span>':''});`,marca?'si':'')}
${tooltip?`<div class="sube" role="tooltip" style="position:absolute;left:330px;top:4px;width:340px;padding:10px 12px;border-radius:12px;background:#FFFFFF;color:${C.tinta};font:14px/1.5 Inter,sans-serif;box-shadow:0 12px 28px rgba(0,0,0,.35)"><strong>leerNumero()</strong> toma la siguiente línea que entra y la vuelve número. <a href="E-Leccion.dc.html" style="font-weight:700;color:${C.tinta}">En la lección ›</a></div>`:''}
</div>`;

