P['E-Ejercicio'] = { t:'Estudiante · Programar · qué hacer, hazlo y ¿cumplo?', h:1080, html: marcoV6({ cols:'340px minmax(0,1fr) 290px', izq: zonaQue, der: zonaCumplo(false), centro: barraEditorV6('estandar') + editorV6(false,true) + consolaTerminal('espera') }) };
P['E-Ejercicio-Casos'] = { t:'Estudiante · Programar · después de Probar casos', h:1080, html: marcoV6({ cols:'340px minmax(0,1fr) 290px', izq: zonaQue, der: zonaCumplo(true), centro: barraEditorV6('estandar') + editorV6(true,false) + consolaTerminal('fin') }) };
P['E-Ejercicio-Grande'] = { t:'Estudiante · Programar · código grande', h:1080, html: marcoV6({ cols:'52px minmax(0,1fr) 52px', izq: franja('¿Qué tengo que hacer?','right',1), der: franja('¿Cumplo?','left',3), centro: barraEditorV6('codigo') + editorV6(true,false) + consolaTerminal('fin') }) };

