// Bloques: es un programa, así que lleva consola como Programar. En el centro, la caja de piezas y el área de armado.
const pieza = (t, col, ind=0) => `<span style="display:inline-flex;align-items:center;gap:6px;margin-left:${ind*22}px;padding:9px 14px;border-radius:10px 10px 10px 4px;background:${col};color:#FFFFFF;font-size:14px;font-weight:700;box-shadow:inset 0 -3px 0 rgba(0,0,0,.18);width:max-content">${t}</span>`;
