<div style="flex:1;padding:14px 0;font:15px/2 'JetBrains Mono',monospace">${ln(1,`${tg('h1')}Arepa con queso${tg('/h1')}`)}${ln(2,`${tg('p')}Fácil y rica para el desayuno.${tg('/p')}`)}${ln(3,tg('ul'))}${ln(4,`  ${tg('li')}Masa de maíz${tg('/li')}`)}${ln(5,`  ${tg('li')}Queso costeño${tg('/li')}`)}${ln(6,`${tg('/ul')}<span class="cursor" style="display:inline-block;width:2px;height:18px;background:#FDE68A;vertical-align:middle;margin-left:2px"></span>`)}</div>
