// enunciado o acá»). Como las tres vistas de Programar: un selector en la barra, sin ventanas. Lo que se recuerda por estudiante.
{ const VH = [['Estándar','E-Tipo-Html'],['Reglas con el enunciado','E-Tipo-Html-Reglas'],['Código grande','E-Tipo-Html-Codigo']];
  const segH = (on) => `<span role="group" aria-label="Vista del ejercicio" style="margin-left:auto;display:flex;padding:3px;border-radius:10px;background:${C.fondo};border:1px solid ${C.borde}">${VH.map(([t,h])=>`<a href="${h}.dc.html" ${t===on?'aria-pressed="true" ':''}style="padding:6px 12px;border-radius:8px;font-size:13px;font-weight:700;text-decoration:none;color:${t===on?C.tinta:C.suave};${t===on?'background:#FFFFFF;box-shadow:0 1px 3px rgba(20,33,61,.15)':''}">${t}</a>`).join('')}</span>`;
  const base = P['E-Tipo-Html'].html;
  const guard = `<span style="margin-left:auto;display:flex;align-items:center;gap:6px;font-size:13px;color:${C.mentaT};font-weight:700">`;
  if (!base.includes(guard) || !base.includes(izqH+editorH+derH)) throw new Error('vistas HTML: no encontré las piezas');
  const conSeg = (on) => base.replace(guard, segH(on) + guard.replace('margin-left:auto;',''));
  const i1 = derH.indexOf('\n<div style="height:330px');
  const head = derH.slice(derH.indexOf('<div'), i1);
  const i2 = derH.indexOf('\n<div style="height:40px', i1);
  const cuerpoPrev = derH.slice(i1, i2).replace('height:330px;flex:none', 'flex:1');
  const i3 = derH.indexOf('\n<div style="flex:1;min-height:0;overflow:hidden;padding:12px');
  const i4 = derH.indexOf('\n<div style="flex:none;display:flex;gap:8px;padding:12px;border-top');
  const lista = derH.slice(i3, i4), botones = derH.slice(i4, derH.lastIndexOf('</aside>'));
  const pest = (t, on, extra='') => `<span style="display:flex;align-items:center;gap:6px;white-space:nowrap;height:42px;padding:0 10px;border-radius:10px 10px 0 0;font-size:13px;font-weight:700;${on?`background:#FFFFFF;border-top:3px solid ${C.sol}`:`color:${C.suave};border-top:3px solid transparent`}">${t}${extra}</span>`;
  const izqReglas = `<aside aria-label="Reglas a cumplir" style="width:400px;flex:none;display:flex;flex-direction:column;min-height:0;background:#FFFFFF;border-right:1px solid ${C.borde}"><div style="display:flex;align-items:center;gap:2px;padding:8px 10px 0;border-bottom:1px solid ${C.borde};background:${C.fondo}">${pest(I('aprender',14)+'Lo que pide el profe',false)}${pest(I('ok',14)+'Reglas',true,` <span style="font-size:11px;padding:1px 7px;border-radius:99px;background:${C.solClaro};color:${C.solT}">3/4</span>`)}<span style="margin-left:auto;display:flex;align-items:center;gap:6px;font-size:12px;font-weight:700;color:${C.suave}">${I('plegar',15)}Plegar</span></div>${lista}${botones}</aside>`;
  const derPrev = `<aside aria-label="Vista previa" style="white-space:nowrap;flex:1;min-width:420px;display:flex;flex-direction:column;background:#FFFFFF;border-left:1px solid ${C.borde}">${head}${cuerpoPrev}</aside>`;
  const franja = `<a href="E-Tipo-Html.dc.html" aria-label="Ver lo que pide el profe" style="width:52px;flex:none;display:flex;flex-direction:column;align-items:center;gap:10px;padding-top:14px;background:#FFFFFF;border-right:1px solid ${C.borde};text-decoration:none;color:${C.tinta}">${I('aprender',18)}<span style="writing-mode:vertical-rl;font-size:13px;font-weight:700">Lo que pide el profe · paso 4 de 4</span></a>`;
  P['E-Tipo-Html'].html = conSeg('Estándar');
  P['E-Tipo-Html-Reglas'] = { t:'Estudiante · HTML y CSS · reglas con el enunciado', h:1080, html: conSeg('Reglas con el enunciado').replace(izqH+editorH+derH, izqReglas + editorH.replace('flex:1;min-width:0','flex:none;width:540px') + derPrev) };
  const franjaPrev = `<a href="E-Tipo-Html.dc.html" aria-label="Mostrar la vista previa y las reglas" style="width:56px;flex:none;display:flex;flex-direction:column;align-items:center;gap:12px;padding-top:14px;background:#FFFFFF;border-left:1px solid ${C.borde};text-decoration:none;color:${C.tinta}">${I('ojo',18)}<span style="writing-mode:vertical-rl;font-size:13px;font-weight:700">Vista previa</span><span style="font-size:11px;font-weight:700;padding:2px 6px;border-radius:99px;background:${C.solClaro};color:${C.solT}">3/4</span><span style="writing-mode:vertical-rl;font-size:12px;color:${C.suave}">reglas</span></a>`;
  P['E-Tipo-Html-SinPrevia'] = { t:'Estudiante · HTML y CSS · sin vista previa por un momento', h:1080, html: conSeg('Estándar').replace(izqH+editorH+derH, izqH + editorH + franjaPrev).replace('Guardado</span>', 'Guardado</span>' + boton('E-Tipo-Html.dc.html',I('play',14)+' Probar','sec','height:40px') + boton('E-Logrado.dc.html','Entregar solución','principal','height:40px')) };
  P['E-Tipo-Html-Codigo'] = { t:'Estudiante · HTML y CSS · código grande', h:1080, html: conSeg('Código grande').replace(izqH+editorH+derH, franja + editorH + derH) };
}

