// ================= MIS PROYECTOS (10/11) =================
// Jeider: «se te está olvidando lo de Mis proyectos y lo de pseudocódigo y diagramas de flujo… verifica el inventario».
// Real: pages/estudiante/proyectos/index.vue y [id].vue, utils/proyectoNavegador.ts (web, javascript, pseudocodigo, diagrama;
// 20 proyectos, 10 archivos y 200 KB cada uno; corren en el navegador), utils/pseudocodigo.ts (estilo PSeInt, cada «Leer»
// toma la siguiente línea de la Entrada, errores con la línea y en palabras del estudiante), utils/diagramaFlujo.ts (inicio,
// fin, entrada, proceso, decisión, salida; se ejecuta con las mismas instrucciones que el pseudocódigo),
// components/proyectos/EditorDiagrama.vue, PaletaFiguras.vue, PanelEdicionDiagrama.vue, ResultadoProyecto.vue (Página con
// ancho de pantalla y consola; Entrada y Salida del programa; se detiene a los 3 s), EnviarAlDocente.vue («Entregar a tu docente»).
{
const TP = { web:['Página web','#1D6FD1','#E3F4FF','HTML, CSS y JavaScript, con la página a la vista'], javascript:['JavaScript','#7C3AED','#EFE8FF','Programas que leen datos y muestran resultados'], pseudocodigo:['Pseudocódigo','#0A7F70','#D5F6F0','Algoritmos al estilo PSeInt que se pueden ejecutar'], diagrama:['Diagrama de flujo','#A35F00','#FFF1C2','Figuras unidas con flechas que también se ejecutan'] };
const icTP = { web:'<circle cx="12" cy="12" r="8.5"/><path d="M3.5 12h17M12 3.5c2.5 2.6 3.7 5.4 3.7 8.5s-1.2 5.9-3.7 8.5c-2.5-2.6-3.7-5.4-3.7-8.5s1.2-5.9 3.7-8.5z"/>', javascript:'<path d="M8 8l-4 4 4 4M16 8l4 4-4 4M13.5 5l-3 14"/>', pseudocodigo:'<path d="M5 5h14M5 10h10M5 15h14M5 20h8"/>', diagrama:'<rect x="8" y="3" width="8" height="5" rx="2.5"/><path d="M12 8v3"/><path d="M12 11l4 3-4 3-4-3z"/><path d="M12 17v4"/>' };
const icoTP = (t, s=18) => `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icTP[t]}</svg>`;
const pastTP = (t, s=40) => `<span style="width:${s}px;height:${s}px;flex:none;border-radius:12px;display:flex;align-items:center;justify-content:center;background:${TP[t][2]};color:${TP[t][1]}">${icoTP(t, s*.5)}</span>`;
const tipoCard = (t, on) => `<span style="flex:1;display:flex;flex-direction:column;gap:8px;padding:14px;border-radius:14px;border:${on?'2px solid '+TP[t][1]:'1px solid '+C.borde};background:${on?TP[t][2]:'#FFFFFF'}">${pastTP(t,36)}<strong style="font-size:15px">${TP[t][0]}</strong><span style="font-size:13px;color:${C.suave};line-height:1.4">${TP[t][3]}</span></span>`;
const filaP = (t, nombre, meta, href, ent='') => `<div class="alza" style="display:flex;align-items:center;gap:14px;padding:14px 16px;border-radius:16px;border:1px solid ${C.borde};background:#FFFFFF">${pastTP(t)}<span style="flex:1;min-width:0"><span style="display:block;font-size:16px;font-weight:700">${nombre}</span><span style="display:block;font-size:13px;color:${C.suave}">${TP[t][0]} · ${meta}</span></span>${ent}${boton(href+'.dc.html','Abrir','principal','height:40px')}<span aria-label="Borrar ${nombre}" title="Borrar" style="width:40px;height:40px;border-radius:10px;border:1px solid ${C.borde};display:flex;align-items:center;justify-content:center;color:${C.suave}">🗑</span></div>`;
P['E-Proyectos'] = { t:'Estudiante · Mis proyectos', h:1000, html: conMenu('proyectos', miga('Mis proyectos'), `
${tarjeta(`<div style="display:flex;align-items:flex-start;gap:16px"><div style="flex:1"><h1 style="margin:0;font-family:Poppins,sans-serif;font-size:26px">Mis proyectos</h1><p style="margin:6px 0 0;font-size:15px;color:${C.suave};line-height:1.5">Tu espacio para programar lo que quieras, sin nota ni intentos. Solo tú los ves y corren en tu navegador.</p></div><span style="font-size:13px;color:${C.suave};text-align:right">3 de 20 proyectos<br>10 archivos y 200 KB cada uno</span></div>`)}
${tarjeta(`${h2('Nuevo proyecto')}<div style="display:flex;gap:10px;margin-bottom:14px">${tipoCard('web',false)}${tipoCard('javascript',false)}${tipoCard('pseudocodigo',true)}${tipoCard('diagrama',false)}</div><div style="display:flex;align-items:flex-end;gap:10px"><label style="flex:1;display:flex;flex-direction:column;gap:6px;font-size:14px;font-weight:700">Nombre<span style="height:44px;display:flex;align-items:center;padding:0 12px;border:1px solid #CBD5E1;border-radius:12px;font-weight:400;color:${C.suave}">Mi calculadora</span></label>${boton('E-Proyecto-Pseudo.dc.html','+ Crear proyecto','principal')}</div>`)}
<div style="display:flex;flex-direction:column;gap:10px">${rotulo('TUS PROYECTOS')}
${filaP('web','CLICK','menos de 1 KB · editado el 31 de oct.','E-Proyecto-Web')}
${filaP('diagrama','if else','menos de 1 KB · editado el 2 de oct.','E-Proyecto-Diagrama',chip('Entregado a «Taller 2»',C.verdeC,C.verde))}
${filaP('pseudocodigo','Promedio de notas','1 KB · editado hoy','E-Proyecto-Pseudo')}
${filaP('javascript','Mi calculadora','2 KB · editado el 30 de sept.','E-Proyecto-JS')}</div>`, 1000) };

// Editor de proyecto: cabecera como la desplegada (volver, nombre editable, guardado, tamaño, descargar, entregar) y dos
// mitades: los archivos y el código a la izquierda; a la derecha lo que el proyecto produce (página, o entrada y salida).
const cab = (t, nombre, extra='') => `<header style="display:flex;align-items:center;gap:12px;padding:12px 16px;border-radius:16px;background:#FFFFFF;border:1px solid ${C.borde}"><a href="E-Proyectos.dc.html" aria-label="Volver a mis proyectos" style="width:38px;height:38px;border-radius:10px;border:1px solid ${C.borde};display:flex;align-items:center;justify-content:center;color:${C.tinta}">${I('izq',16)}</a>${pastTP(t,34)}<span style="flex:1;min-width:0"><span style="display:block;font-size:17px;font-weight:700">${nombre} <span style="font-size:12px;font-weight:400;color:${C.suave}">· toca para cambiar el nombre</span></span><span style="display:block;font-size:12px;color:${C.suave}">${TP[t][0]}</span></span><span style="display:flex;align-items:center;gap:6px;font-size:13px;font-weight:700;color:${C.mentaT}">${I('guardado',14)}Guardado</span><span style="font-size:12px;color:${C.suave}">1 KB de 200 KB</span>${extra}<span style="height:36px;display:flex;align-items:center;gap:6px;padding:0 12px;border-radius:10px;border:1px solid #CBD5E1;font-size:13px;font-weight:700">${I('entrega',14)}.zip</span>${boton('E-Proyectos.dc.html',I('enviar',15)+' Entregar a tu docente','sol','height:38px;font-size:14px')}</header>`;
const archivos = (lista, act) => `<div role="tablist" aria-label="Archivos" style="height:44px;flex:none;display:flex;align-items:center;gap:4px;padding:0 10px;background:#111A2E;border-bottom:1px solid #1E293B">${lista.map(a=>`<span role="tab" aria-selected="${a===act}" style="padding:6px 12px;border-radius:8px;font:600 13px 'JetBrains Mono',monospace;${a===act?'background:#0F172A;border:1px solid #334155;color:#FFFFFF':'color:#A7B4C8'}">${a}</span>`).join('')}<span aria-label="Agregar archivo" title="Agregar archivo" style="padding:4px 10px;color:#A7B4C8;font-size:16px;font-weight:700">+</span></div>`;
const codigo = (lineas) => `<div style="flex:1;min-height:0;background:#0F172A;padding:12px 0;font:15px/1.95 'JetBrains Mono',monospace;color:#E2E8F0;font-variant-ligatures:none">${lineas.map((l,i)=>`<div style="display:flex;white-space:pre"><span style="width:44px;flex:none;text-align:right;padding-right:14px;color:#8A9BB4">${i+1}</span><span>${l}</span></div>`).join('')}</div>`;
const kw = (t) => `<span style="color:#C4B5FD">${t}</span>`, fn = (t) => `<span style="color:#5EEAD4">${t}</span>`, tx = (t) => `<span style="color:#86EFAC">${t}</span>`, tg = (t) => `<span style="color:#93C5FD">&lt;${t}&gt;</span>`;
const izqEd = (lista, act, lineas) => `<section aria-label="Código" style="flex:1;min-width:0;display:flex;flex-direction:column;border-radius:16px;overflow:hidden;border:1px solid #1E293B">${archivos(lista, act)}${codigo(lineas)}</section>`;
const entradaSalida = (entrada, salida, notaEntrada) => `<section aria-label="Resultado" style="flex:1;min-width:0;display:flex;flex-direction:column;gap:0;border-radius:16px;overflow:hidden;border:1px solid ${C.borde};background:#FFFFFF">
<div style="padding:14px 16px;display:flex;flex-direction:column;gap:8px;border-bottom:1px solid ${C.borde}"><label style="font-size:14px;font-weight:700">Entrada <span style="font-weight:400;color:${C.suave}">· ${notaEntrada}</span></label><span style="min-height:76px;padding:8px 12px;border:1px solid #CBD5E1;border-radius:12px;font:15px/1.7 'JetBrains Mono',monospace">${entrada}</span><span style="display:flex;gap:8px">${boton('#',I('play',14)+' Ejecutar','sol','height:40px')}<span style="font-size:12px;color:${C.suave};align-self:center">Se detiene solo a los 3 segundos si algo no termina.</span></span></div>
<div style="flex:1;background:#0B1222;color:#E2E8F0;padding:12px 16px;font:15px/1.9 'JetBrains Mono',monospace;font-variant-ligatures:none"><span style="display:block;font:700 12px Inter,sans-serif;color:#A7B4C8;margin-bottom:6px">SALIDA DEL PROGRAMA</span>${salida}</div></section>`;
const marcoProy = (t, nombre, cuerpo) => conMenu('proyectos', miga('Mis proyectos', nombre), `${cab(t, nombre)}<div style="flex:1;min-height:0;display:flex;gap:14px">${cuerpo}</div>`, 1000);

P['E-Proyecto-Web'] = { t:'Estudiante · Proyecto · Página web', h:1000, html: marcoProy('web','CLICK', izqEd(['index.html','estilos.css','app.js'],'index.html',[`${tg('h1')}¡Haz clic!${tg('/h1')}`,`${tg('button id="boton"')}Contar${tg('/button')}`,`${tg('p id="total"')}0${tg('/p')}`,`${tg('script src="app.js"')}${tg('/script')}`]) + `<section aria-label="Resultado" style="flex:1;min-width:0;display:flex;flex-direction:column;border-radius:16px;overflow:hidden;border:1px solid ${C.borde};background:#FFFFFF"><div style="height:44px;flex:none;display:flex;align-items:center;gap:8px;padding:0 12px;border-bottom:1px solid ${C.borde};font-size:14px;font-weight:700">${I('ojo',15)}Página<span role="group" aria-label="Ancho de la pantalla" style="margin-left:auto;display:flex;padding:3px;border-radius:9px;background:${C.fondo}">${['Celular','Tableta','Computador'].map((x,i)=>`<span style="padding:4px 10px;border-radius:7px;font-size:12px;${i===2?'background:#FFFFFF;box-shadow:0 1px 3px rgba(20,33,61,.15)':`color:${C.suave}`}">${x}</span>`).join('')}</span><span style="display:flex;align-items:center;gap:4px;font-size:12px">${I('max',13)}En grande</span></div><div style="flex:1;padding:24px;font-family:Georgia,serif"><h1 style="margin:0 0 12px">¡Haz clic!</h1><span style="display:inline-block;padding:6px 14px;border:1px solid #888;border-radius:4px;font-family:Arial">Contar</span><p style="font-size:22px">3</p></div><div style="height:150px;flex:none;background:#0B1222;color:#E2E8F0;padding:10px 14px;font:14px/1.8 'JetBrains Mono',monospace"><span style="display:block;font:700 12px Inter,sans-serif;color:#A7B4C8">CONSOLA DE LA PÁGINA</span>clic número 1<br>clic número 2<br>clic número 3</div></section>`) };
P['E-Proyecto-JS'] = { t:'Estudiante · Proyecto · JavaScript', h:1000, html: marcoProy('javascript','Mi calculadora', izqEd(['main.js','util.js'],'main.js',[`${kw('const')} a = ${fn('Number')}(${fn('leerEntrada')}().${fn('split')}(${tx("'\\n'")})[0]);`,`${kw('const')} b = ${fn('Number')}(${fn('leerEntrada')}().${fn('split')}(${tx("'\\n'")})[1]);`,'',`${fn('console.log')}(${tx("'Suma:'")}, a + b);`,`${fn('console.log')}(${tx("'Resta:'")}, a - b);`]) + entradaSalida('8<br>5','Suma: 13<br>Resta: 3<br><span style="color:#94A3B8">terminó en 3 ms</span>','un dato por línea; leerEntrada() la lee completa')) };
P['E-Proyecto-Pseudo'] = { t:'Estudiante · Proyecto · Pseudocódigo', h:1000, html: marcoProy('pseudocodigo','Promedio de notas', `<div style="flex:1;min-width:0;display:flex;flex-direction:column;gap:10px">${izqEd(['algoritmo.psc','notas.txt'],'algoritmo.psc',[`${kw('Algoritmo')} Promedio`,`    ${kw('Definir')} n1, n2, prom ${kw('Como')} Real`,`    ${kw('Escribir')} ${tx('"Primera nota:"')}`,`    ${kw('Leer')} n1`,`    ${kw('Escribir')} ${tx('"Segunda nota:"')}`,`    ${kw('Leer')} n2`,`    prom &lt;- (n1 + n2) / 2`,`    ${kw('Si')} prom &gt;= 3 ${kw('Entonces')}`,`        ${kw('Escribir')} ${tx('"Aprobaste con "')}, prom`,`    ${kw('SiNo')}`,`        ${kw('Escribir')} ${tx('"Te falta, llevas "')}, prom`,`    ${kw('FinSi')}`,`${kw('FinAlgoritmo')}`])}<details style="border:1px solid ${C.borde};border-radius:14px;padding:10px 14px;background:#FFFFFF"><summary style="cursor:pointer;font-size:14px;font-weight:700">Palabras que puedes usar (al estilo PSeInt)</summary><p style="margin:8px 0 0;font-size:13px;line-height:1.6">Leer, Escribir, Definir… Como, Si… Entonces… SiNo… FinSi, Mientras… Hacer, Para… Hasta, Repetir… Hasta Que. ${'<a href="E-Leccion.dc.html" style="font-weight:700;color:'+C.tinta+'">Repasar «Pseudocódigo y diagramas» · 2 min</a>'}</p></details></div>` + entradaSalida('4.2<br>2.6','Primera nota:<br>Segunda nota:<br>Aprobaste con 3.4<br><span style="color:#94A3B8">terminó en 2 ms</span>','un dato por línea; cada <strong>Leer</strong> toma el siguiente')) };

// Diagrama de flujo: paleta con las figuras del curso, el lienzo, el panel de la figura elegida y la ejecución.
const fig = (tipo, x, y, w, h, texto, sel=false) => { const col = {inicio:['#D5F6F0','#0A7F70'],fin:['#D5F6F0','#0A7F70'],entrada:['#E3F4FF','#1D6FD1'],salida:['#E3F4FF','#1D6FD1'],proceso:['#FFFFFF','#14213D'],decision:['#FFF1C2','#A35F00']}[tipo]; const sw = sel?3:2, st = sel?C.sol:col[1]; const forma = tipo==='inicio'||tipo==='fin' ? `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${h/2}" fill="${col[0]}" stroke="${st}" stroke-width="${sw}"/>` : tipo==='entrada'||tipo==='salida' ? `<path d="M${x+16} ${y}h${w}l-16 ${h}h-${w}z" fill="${col[0]}" stroke="${st}" stroke-width="${sw}"/>` : tipo==='decision' ? `<path d="M${x+w/2} ${y}l${w/2} ${h/2}-${w/2} ${h/2}-${w/2}-${h/2}z" fill="${col[0]}" stroke="${st}" stroke-width="${sw}"/>` : `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="6" fill="${col[0]}" stroke="${st}" stroke-width="${sw}"/>`; return `${forma}<text x="${x+w/2+(tipo==='entrada'||tipo==='salida'?8:0)}" y="${y+h/2+5}" text-anchor="middle" font-family="Inter,sans-serif" font-size="14" font-weight="600" fill="#14213D">${texto}</text>`; };
const fl = (d) => `<path d="${d}" fill="none" stroke="#64748B" stroke-width="2" marker-end="url(#pf)"/>`;
const lienzo = `<svg width="100%" height="100%" viewBox="0 0 560 600" role="img" aria-label="Diagrama: Inicio, leer edad, si edad es mayor o igual a 18 escribe Puedes votar, si no escribe Todavía no, Fin"><defs><marker id="pf" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0L10 5L0 10z" fill="#64748B"/></marker></defs>
${fig('inicio',220,20,120,44,'Inicio')}${fl('M280 64v32')}${fig('entrada',200,98,150,48,'Leer edad')}${fl('M280 146v34')}${fig('decision',190,182,180,96,'edad >= 18',true)}
${fl('M190 230H110v76')}<text x="140" y="222" font-family="Inter,sans-serif" font-size="13" font-weight="700" fill="#047857">Sí</text>${fl('M370 230h80v76')}<text x="396" y="222" font-family="Inter,sans-serif" font-size="13" font-weight="700" fill="#B42318">No</text>
${fig('salida',30,308,170,48,'"Puedes votar"')}${fig('salida',360,308,170,48,'"Todavía no"')}${fl('M115 356v70h150')}${fl('M445 356v70H295')}${fig('fin',220,404,120,44,'Fin')}
<text x="280" y="520" text-anchor="middle" font-family="Inter,sans-serif" font-size="13" fill="#4A5873">Arrastra las figuras · une con flechas desde el punto de abajo</text></svg>`;
const paleta = `<aside aria-label="Herramientas para agregar figuras" style="width:150px;flex:none;display:flex;flex-direction:column;gap:8px;padding:12px;background:#FFFFFF;border-right:1px solid ${C.borde}"><strong style="font-size:13px">Agregar figura</strong>${[['Inicio / Fin','óvalo','#0A7F70'],['Leer','entrada','#1D6FD1'],['Proceso','x <- valor','#14213D'],['Decisión','Sí / No','#A35F00'],['Escribir','salida','#1D6FD1']].map(([t,d,c])=>`<span style="display:flex;flex-direction:column;padding:8px 10px;border-radius:10px;border:1px solid ${C.borde};border-left:4px solid ${c}"><strong style="font-size:13px">${t}</strong><span style="font-size:11px;color:${C.suave}">${d}</span></span>`).join('')}</aside>`;
const panelFig = `<div aria-label="Panel de edición" style="padding:12px 14px;border-top:1px solid ${C.borde};display:flex;flex-direction:column;gap:8px;background:${C.fondo}"><div style="display:flex;align-items:center"><strong style="flex:1;font-size:14px">Decisión</strong><span aria-label="Cerrar el panel de Decisión" style="color:${C.suave}">✕</span></div><label style="display:flex;flex-direction:column;gap:4px;font-size:13px;font-weight:700">Contenido<span style="padding:8px 10px;border:1px solid #CBD5E1;border-radius:10px;background:#FFFFFF;font:400 14px 'JetBrains Mono',monospace;font-variant-ligatures:none">edad &gt;= 18</span></label><span style="font-size:12px;color:${C.suave}">La flecha «Sí» va a «Puedes votar» y la «No», a «Todavía no».</span><span style="font-size:13px;font-weight:700;color:#B42318">Borrar figura</span></div>`;
P['E-Proyecto-Diagrama'] = { t:'Estudiante · Proyecto · Diagrama de flujo', h:1000, html: marcoProy('diagrama','if else', `<section aria-label="Diagrama" style="flex:1.3;min-width:0;display:flex;border-radius:16px;overflow:hidden;border:1px solid ${C.borde};background:#FFFFFF">${paleta}<div style="flex:1;display:flex;flex-direction:column;min-width:0"><div style="flex:1;min-height:0;padding:8px;background-image:radial-gradient(#E3EAF3 1.2px,transparent 1.2px);background-size:18px 18px">${lienzo}</div>${panelFig}</div></section>` + entradaSalida('20','Puedes votar<br><span style="color:#94A3B8">pasó por: Inicio › Leer edad › edad &gt;= 18 (Sí) › Escribir › Fin</span>','un dato por línea; cada figura <strong>Leer</strong> toma el siguiente')) };
}

