for (const [k, v] of Object.entries(P)) if (k.startsWith('E-')) v.html = v.html.split('href="E-Inicio.dc.html" role="button" aria-haspopup="menu"').join('href="E-Clases.dc.html"');
P['E-Cuenta'].html = P['E-Cuenta'].html.replace(/href="E-Cuenta\.dc\.html"([^>]*>(?:(?!<\/a>)[\s\S])*Unirme con un código)/, 'href="E-Clases.dc.html"$1');

