const filtro = (ts, act) => `<div style="display:flex;gap:6px;flex-wrap:wrap">${ts.map(t=>`<span style="height:32px;display:flex;align-items:center;padding:0 11px;border-radius:999px;font-size:13px;font-weight:700;${t===act?`background:${C.tinta};color:#FFFFFF`:`border:1px solid ${C.borde};background:#FFFFFF`}">${t}</span>`).join('')}</div>`;
