const caja = (on, parcial) => `<span aria-hidden="true" style="width:18px;height:18px;flex:none;border-radius:5px;${on||parcial?`background:${C.tinta};color:#FFFFFF`:'border:2px solid #94A3B8;box-sizing:border-box'};display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700">${on?'✓':parcial?'–':''}</span>`;
