// ---------- Cómo recuerda tu clase: la repetición espaciada vista por el docente (review-schedules: próxima fecha, intervalo, repeticiones, fallos) ----------
{
// Curva del olvido de un tema: baja y cada repaso la sube; la clase en promedio
const W=640,H=230,x0=40,y0=20,yb=200;
const pts=[]; let r=100; const repasos=[2,6,14]; let t0=0;
for(let d=0; d<=21; d+=0.25){ if(repasos.includes(Math.round(d*4)/4) && d>0 && Math.abs(d-Math.round(d))<0.01){ r=Math.min(100,r+(100-r)*0.85); t0=d; } const k=[0.18,0.09,0.045,0.025][repasos.filter(x=>x<=d).length]; pts.push([d, r*Math.exp(-k*(d-t0))]); if(Math.abs(d-Math.round(d))<0.01 && repasos.includes(d)) {} }
// recalcular sin saltos dobles
let path='', rr=100, tt=0; const P2=[];
for(let d=0; d<=21.001; d+=0.25){ const n=repasos.filter(x=>x<=d).length; const k=[0.16,0.08,0.04,0.02][n]; if(repasos.includes(d)){ rr = 96; tt=d; } const v = rr*Math.exp(-k*(d-tt)); P2.push([d,v]); }
const X=d=>x0+d/21*(W-x0-20), Y=v=>yb-(v/100)*(yb-y0);
path = P2.map(([d,v],i)=>(i?'L':'M')+X(d).toFixed(1)+' '+Y(v).toFixed(1)).join(' ');
const sinRep = Array.from({length:85},(_,i)=>i*0.25).map((d,i)=>(i?'L':'M')+X(d).toFixed(1)+' '+Y(100*Math.exp(-0.16*d)).toFixed(1)).join(' ');
const curva = `<svg viewBox="0 0 ${W} ${H+20}" width="100%" role="img" aria-label="Recuerdo de la clase en Operadores: sin repasos cae a menos del 10 % en tres semanas; con repasos los días 2, 6 y 14 se mantiene sobre el 60 %">
${[0,25,50,75,100].map(v=>`<line x1="${x0}" x2="${W-20}" y1="${Y(v)}" y2="${Y(v)}" stroke="#E3EAF3"/><text x="${x0-8}" y="${Y(v)+4}" text-anchor="end" font-size="11" fill="#4A5873">${v}%</text>`).join('')}
${[0,7,14,21].map(d=>`<text x="${X(d)}" y="${yb+18}" text-anchor="middle" font-size="11" fill="#4A5873">${d===0?'Lección':'Día '+d}</text>`).join('')}
<path d="${sinRep}" fill="none" stroke="#94A3B8" stroke-width="2" stroke-dasharray="5 5"/>
<path class="dibuja" pathLength="100" d="${path}" fill="none" stroke="#00C2A8" stroke-width="3.5" stroke-linejoin="round"/>
${repasos.map((d,i)=>`<g><circle cx="${X(d)}" cy="${Y(96)}" r="7" fill="#FFC94D" stroke="#14213D" stroke-width="2"/><text x="${X(d)}" y="${Y(96)-13}" text-anchor="middle" font-size="11" font-weight="700" fill="#14213D">Repaso ${i+1}</text></g>`).join('')}
<line x1="${X(9)}" x2="${X(9)}" y1="${y0}" y2="${yb}" stroke="#14213D" stroke-width="1.5" stroke-dasharray="3 4"/><text x="${X(9)+6}" y="${y0+12}" font-size="11" font-weight="700" fill="#14213D">Esta semana</text>
<text x="${X(17)}" y="${Y(8)-6}" font-size="11" fill="#4A5873">Sin repasos</text>
</svg>`;
const dias = [['Lun',18,16],['Mar',22,19],['Mié',25,14],['Jue',12,0],['Vie',9,0],['Sáb',4,0],['Dom',3,0]];
const maxD=25;
const cal = `<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:10px;align-items:end;height:170px">${dias.map(([d,v,h],i)=>`<div style="display:flex;flex-direction:column;align-items:center;gap:6px;height:100%;justify-content:flex-end"><span style="font-size:12px;font-weight:700">${v}</span><span class="crece" style="position:relative;width:100%;max-width:46px;height:${v/maxD*120}px;border-radius:10px 10px 4px 4px;background:${i<3?'#E3EAF3':'#C9F0E9'};overflow:hidden;animation-delay:${i*0.06}s">${h?`<span style="position:absolute;left:0;right:0;bottom:0;height:${h/v*100}%;background:${C.tq}"></span>`:''}</span><span style="font-size:12px;color:${i===2?C.tinta:C.suave};font-weight:${i===2?700:500}">${d}</span></div>`).join('')}</div><div style="display:flex;gap:14px;margin-top:10px;font-size:12px"><span style="display:flex;align-items:center;gap:6px"><span style="width:12px;height:12px;border-radius:3px;background:${C.tq}"></span>Hechos a tiempo</span><span style="display:flex;align-items:center;gap:6px"><span style="width:12px;height:12px;border-radius:3px;background:#E3EAF3"></span>Vencieron sin hacer</span><span style="display:flex;align-items:center;gap:6px"><span style="width:12px;height:12px;border-radius:3px;background:#C9F0E9"></span>Vienen</span></div>`;
const temas = [['Operadores y expresiones',58,'baja',11,'Repasarlo en clase'],['Variables y tipos de datos',81,'estable',4,''],['Pseudocódigo y diagramas',74,'estable',6,''],['Algoritmos en la vida diaria',90,'sube',1,'']];
const est = [['SR','Santiago Ramírez','Al día',0,9,[C.menta,C.mentaT],''],['LG','Laura Gómez','Al día',0,12,[C.menta,C.mentaT],''],['CD','Camilo Díaz','5 pendientes',5,2,[C.solClaro,C.solT],'Recordarle'],['VR','Valentina Ríos','3 pendientes',3,4,[C.solClaro,C.solT],'Darle menos por día'],['AP','Andrés Pérez','Sin empezar',8,0,[C.fondo,C.suave],'Escribirle']];
const curvaCard = tarjeta(h2('Cuánto recuerda la clase', `<span style="display:flex;gap:6px">${['Operadores','Variables','Pseudocódigo'].map((t,i)=>`<span style="padding:6px 10px;border-radius:999px;font-size:12px;font-weight:700;${i?`background:${C.fondo};color:${C.tinta}`:`background:${C.tinta};color:#FFFFFF`}">${t}</span>`).join('')}</span>`) + curva + `<div style="display:flex;gap:16px;flex-wrap:wrap;font-size:12px;margin:2px 0 10px"><span style="display:flex;align-items:center;gap:6px"><span style="width:18px;height:3px;background:${C.tq}"></span>Con los repasos de STIRE</span><span style="display:flex;align-items:center;gap:6px"><span style="width:18px;border-top:2px dashed #94A3B8"></span>Sin repasar</span><span style="display:flex;align-items:center;gap:6px"><span style="width:10px;height:10px;border-radius:50%;background:${C.sol};border:2px solid ${C.tinta}"></span>Repaso</span></div><details style="border-top:1px solid ${C.borde};padding-top:10px"><summary style="cursor:pointer;font-size:14px;font-weight:700;color:${C.mentaT}">¿Por qué funcionan los repasos?</summary><p style="margin:8px 0 0;font-size:14px;line-height:1.55">Lo que se aprende se olvida rápido si no vuelve: es la curva del olvido. Cada repaso, justo cuando empieza a olvidarse, lo vuelve a subir y hace que la siguiente caída sea más lenta. Por eso STIRE espacia los repasos: 2 días, luego 6, luego 14. Si alguien falla un repaso, el tema vuelve antes.</p></details>`);
const semanaCard = tarjeta(h2('Repasos de esta semana', `<span style="font-size:13px;color:${C.suave}">93 en total</span>`) + cal + `<p style="margin:10px 0 0;font-size:13px;line-height:1.5;color:${C.suave}">El miércoles se hicieron solo 14 de 25: era día de parcial. <a href="D3-Ajustes.dc.html" style="color:${C.mentaT};font-weight:700">Mover los repasos de ese día</a></p>`);
const temasCard = tarjeta(h2('Qué recuerda de cada tema') + temas.map(([t,p,tend,n,acc])=>`<div style="padding:10px 0;border-top:1px solid ${C.borde}"><div style="display:flex;align-items:center;gap:10px;margin-bottom:6px"><span style="flex:1;font-size:14px;font-weight:700">${t}</span><span style="font-size:13px;font-weight:700;color:${tend==='baja'?C.solT:tend==='sube'?C.mentaT:C.suave}">${tend==='baja'?'↓ se está olvidando':tend==='sube'?'↑ sube':'→ estable'}</span><span style="font-family:Poppins,sans-serif;font-weight:700">${p} %</span></div>${barraProg(p,p<65?C.sol:C.tq,8)}<div style="display:flex;align-items:center;gap:8px;margin-top:6px"><span style="flex:1;font-size:12px;color:${C.suave}">${n} ${n===1?'estudiante falló':'estudiantes fallaron'} el último repaso</span>${acc?boton('D3-Asistente.dc.html',acc,'sec','height:32px;font-size:12px'):''}</div></div>`).join(''));
const estCard = tarjeta(h2('Cómo va cada estudiante', `<a href="D3-Estudiantes.dc.html" style="font-size:14px;font-weight:600;color:${C.mentaT}">Ver los 28</a>`) + est.map(([ini,n,e,atr,racha,[bg,c],acc])=>`<div style="display:grid;grid-template-columns:36px minmax(0,1fr) 150px 150px;gap:12px;align-items:center;padding:10px 2px;border-top:1px solid ${C.borde}"><span style="width:34px;height:34px;border-radius:50%;background:${C.fondo};font-size:12px;font-weight:700;display:flex;align-items:center;justify-content:center">${ini}</span><span style="min-width:0"><span style="display:flex;align-items:center;gap:8px;flex-wrap:wrap"><strong style="font-size:15px">${n}</strong>${chip(e,bg,c)}</span><span style="display:block;font-size:12px;color:${C.suave}">${racha?racha+' días seguidos repasando':'Aún no hace su primer repaso'}</span></span><span style="display:flex;gap:3px" aria-label="Últimos 14 días">${Array.from({length:14},(_,i)=>`<span style="width:8px;height:18px;border-radius:3px;background:${i>=14-racha?C.tq:(i>=14-racha-atr?'#FFE08A':'#E3EAF3')}"></span>`).join('')}</span>${acc?boton(acc==='Escribirle'?'D3-Comunicar.dc.html':'D3-Estudiante.dc.html',acc,'sec','height:34px;font-size:13px;justify-content:center'):'<span></span>'}</div>`).join('') + `<details style="margin-top:10px"><summary style="cursor:pointer;font-size:13px;font-weight:700;color:${C.mentaT}">Cómo leer las barras</summary><p style="margin:6px 0 0;font-size:12px;color:${C.suave}">Cada barra es un día de las últimas dos semanas: turquesa repasó, amarillo se le venció, gris no le tocaba.</p></details>`);
P['D3-Recuerda'] = { t:'Docente · Cómo recuerda tu clase (repetición espaciada)', h:1300, html: conMenuD('repasos', miga('Fundamentos · G2','Repasos de la clase'), `
<div style="display:flex;align-items:flex-end;gap:16px"><div style="flex:1"><h1 style="margin:0;font-family:Poppins,sans-serif;font-size:28px">Cómo recuerda tu clase</h1><p style="margin:4px 0 0;font-size:15px;color:${C.suave}">Si los repasos están funcionando y a quién le hace falta un empujón.</p></div>${boton('D3-Ajustes.dc.html',I('ajustes',16)+' Ajustar los repasos','sec')}</div>
<div style="display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px">${[['Recuerdan en promedio','72 %','de lo que ya vieron',72],['Repasos a tiempo','68 %','esta semana · 49 de 72',68],['Al día','17 de 28','sin repasos pendientes',61],['Se está olvidando','1 tema','Operadores y expresiones',0]].map(([a,b,c,p])=>tarjeta(`${rotulo(a.toUpperCase())}<p style="margin:0;font-family:Poppins,sans-serif;font-size:26px;font-weight:700">${b}</p><p style="margin:2px 0 8px;font-size:13px;color:${C.suave}">${c}</p>${p?barraProg(p,C.tq,6):''}`,'padding:16px 18px')).join('')}</div>
${sugerencia('11 estudiantes fallaron el último repaso de <strong>Operadores y expresiones</strong>. ¿Te preparo 5 minutos de repaso para empezar la próxima clase? Tú lo revisas.','Preparar el repaso','D3-Asistente')}
<div style="display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,1fr);gap:18px;align-items:start">${curvaCard}${semanaCard}</div>
<div style="display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.35fr);gap:18px;align-items:start">${temasCard}${estCard}</div>
`, 1300) };
}

