const preguntar = `<div style="padding:12px 14px;border-radius:14px;border:1px solid ${C.borde};display:flex;flex-direction:column;gap:8px"><p style="margin:0;font-size:14px;font-weight:700">¿A quién le pregunto?</p>${[['Al Tutor','Dudas del tema o del ejercicio','Al instante'],['Al profe','Notas, entregas, permisos','Responde en 1 o 2 días hábiles'],['Sugerencias','Algo de STIRE no funciona o se puede mejorar','Lo revisa el equipo cada semana']].map(([a,b,c])=>`<span style="display:grid;grid-template-columns:90px 1fr;gap:8px;font-size:13px"><strong>${a}</strong><span>${b}<br><span style="color:${C.mentaT};font-weight:600">${c}</span></span></span>`).join('')}</div>`;
